/* @autogenerated */
package net.civeira.phylax.feature.oauth.profile.infrastructure.driven;

import java.time.OffsetDateTime;
import java.util.List;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import org.mockito.Mockito;

import net.civeira.phylax.feature.oauth.profile.domain.WebAuthnCredentialSummary;
import net.civeira.phylax.feature.oauth.webauthn.domain.WebAuthnCredential;
import net.civeira.phylax.feature.oauth.webauthn.domain.gateway.WebAuthnCredentialGateway;

/** The passkeys of the profile, managed through the WebAuthn credentials. */
class ProfileWebAuthnAdapterUnitTest {
  private final WebAuthnCredentialGateway credentials =
      Mockito.mock(WebAuthnCredentialGateway.class);
  private final ProfileWebAuthnAdapter adapter = new ProfileWebAuthnAdapter(credentials);

  @Test
  @DisplayName("The passkeys are listed as summaries")
  void lists_summaries() {
    OffsetDateTime created = OffsetDateTime.now().minusDays(1);
    OffsetDateTime used = OffsetDateTime.now();
    Mockito.when(credentials.findByUser("user-1", "acme"))
        .thenReturn(List.of(
            WebAuthnCredential.builder().uid("k1").credentialId("cred-1").deviceName("Laptop")
                .aaguid("aaguid-1").createdAt(created).lastUsedAt(used).build(),
            WebAuthnCredential.builder().uid("k2").credentialId("cred-2").build()));

    List<WebAuthnCredentialSummary> summaries = adapter.listCredentials("user-1", "acme");

    Assertions.assertEquals(2, summaries.size());
    WebAuthnCredentialSummary first = summaries.get(0);
    Assertions.assertEquals("cred-1", first.getId());
    Assertions.assertEquals("Laptop", first.getName().orElseThrow());
    Assertions.assertEquals("aaguid-1", first.getAaguid().orElseThrow());
    Assertions.assertEquals(created, first.getCreatedAt());
    Assertions.assertEquals(used, first.getLastUsedAt().orElseThrow());
    Assertions.assertTrue(summaries.get(1).getName().isEmpty());
    Assertions.assertTrue(summaries.get(1).getLastUsedAt().isEmpty());
  }

  @Test
  @DisplayName("The name given by the user wins over the device name")
  void name_wins_over_device_name() {
    Mockito.when(credentials.findByUser("user-1", "acme")).thenReturn(List.of(WebAuthnCredential
        .builder().uid("k1").credentialId("cred-1").name("Phone").deviceName("Laptop").build()));

    List<WebAuthnCredentialSummary> summaries = adapter.listCredentials("user-1", "acme");

    Assertions.assertEquals("Phone", summaries.get(0).getName().orElseThrow());
  }

  @Test
  @DisplayName("Rename and delete go to the credentials of the user")
  void rename_and_delete() {
    adapter.renameCredential("cred-1", "user-1", "acme", "Phone");
    adapter.deleteCredential("cred-1", "user-1", "acme");

    Mockito.verify(credentials).rename("cred-1", "user-1", "acme", "Phone");
    Mockito.verify(credentials).delete("cred-1", "user-1", "acme");
  }
}
